<script setup lang="ts">
import{computed,onMounted,ref}from"vue";
import{auth,nodes,inbounds,clients,traffic,audit}from"./api";
const sections=[["dashboard","داشبورد"],["nodes","نودها"],["inbounds","این‌باندها"],["clients","کلاینت‌ها"],["traffic","ترافیک و سهمیه"],["admins","مدیران و RBAC"],["audit","گزارش حسابرسی"],["settings","تنظیمات"]];
const section=ref("dashboard");const email=ref("");const password=ref("");const loginError=ref("");const loading=ref(false);const booting=ref(true);const me=ref<any>(null);const nodeRows=ref<any[]>([]);const inboundRows=ref<any[]>([]);const clientRows=ref<any[]>([]);const auditRows=ref<any[]>([]);const trafficData=ref<any>({});
const title=computed(()=>sections.find(x=>x[0]===section.value)?.[1]??"داشبورد");
async function load(){loading.value=true;try{me.value=await auth.me();const[n,i,c,t,a]=await Promise.all([nodes.list(),inbounds.list(),clients.list(),traffic.summary(),audit.list()]);nodeRows.value=n;inboundRows.value=i;clientRows.value=c;trafficData.value=t;auditRows.value=a}catch(e){if(localStorage.getItem("primevpn_access"))loginError.value=e instanceof Error?e.message:"خطای ارتباط با API"}finally{loading.value=false;booting.value=false}}
async function login(){loginError.value="";loading.value=true;try{const r=await auth.login(email.value,password.value);if(r.mfa_required){loginError.value="این حساب MFA دارد؛ از endpoint تایید MFA استفاده کنید.";return}localStorage.setItem("primevpn_access",r.access_token);await load()}catch(e){loginError.value=e instanceof Error?e.message:"ورود ناموفق"}finally{loading.value=false}}
function logout(){localStorage.removeItem("primevpn_access");me.value=null}
onMounted(load);
</script>
<template>
<div v-if="booting" class="app-shell"><main class="main"><div class="panel page"><div class="empty">در حال اتصال به PRIMEVPN Control Plane…</div></div></main></div>
<div v-else-if="!me" class="login-shell"><div class="login-card"><div class="brand"><span class="brand-mark">P</span><div><b>PRIMEVPN</b><small>Control Plane v100</small></div></div><h1>ورود به پنل</h1><p>مدیریت امن Node، Inbound، Client و Traffic</p><input v-model="email" type="email" placeholder="Email"><input v-model="password" type="password" placeholder="Password" @keyup.enter="login"><button class="primary wide" :disabled="loading" @click="login">{{loading?"در حال ورود…":"ورود"}}</button><div v-if="loginError" class="error-box">{{loginError}}</div></div></div>
<div v-else class="app-shell">
<aside class="sidebar"><div class="brand"><span class="brand-mark">P</span><div><b>PRIMEVPN</b><small>Control Plane v100</small></div></div><nav><button v-for="s in sections" :key="s[0]" :class="{active:section===s[0]}" @click="section=s[0]">{{s[1]}}</button></nav><div class="sidebar-foot"><i></i> {{me.email}} <button @click="logout">خروج</button></div></aside>
<main class="main"><header><div><small>PRIMEVPN / {{title}}</small><h1>{{title}}</h1></div><div class="header-actions"><span class="badge ready">{{me.role}}</span></div></header>
<div v-if="loading" class="panel"><div class="empty">در حال دریافت داده…</div></div>
<section v-else-if="section==='dashboard'"><div class="stats"><article><small>نودها</small><strong>{{nodeRows.length}}</strong><em class="badge ready">READY</em></article><article><small>کلاینت‌ها</small><strong>{{clientRows.length}}</strong><em class="badge active">ACTIVE</em></article><article><small>ترافیک کل</small><strong>{{((trafficData.total_bytes||0)/1099511627776).toFixed(2)}} TB</strong><em class="badge normal">TOTAL</em></article><article><small>این‌باندها</small><strong>{{inboundRows.length}}</strong><em class="badge normal">LIVE</em></article></div><div class="panel"><div class="panel-head"><div><h2>وضعیت نودها</h2><small>داده واقعی از API</small></div></div><div class="table"><div class="tr th"><span>نام</span><span>آدرس</span><span>وضعیت</span><span>آخرین مشاهده</span></div><div class="tr" v-for="n in nodeRows" :key="n.id"><span>{{n.name}}</span><span>{{n.address}}</span><span><em class="badge ready">{{n.state}}</em></span><span>{{n.last_seen_at||"—"}}</span></div><div v-if="!nodeRows.length" class="empty">هیچ نودی ثبت نشده است.</div></div></div></section>
<section v-else-if="section==='nodes'"><div class="panel page"><div class="panel-head"><h2>نودها</h2><button class="primary">+ نود جدید</button></div><div class="table"><div class="tr th"><span>نام</span><span>آدرس</span><span>State</span><span>Agent</span></div><div class="tr" v-for="n in nodeRows" :key="n.id"><span>{{n.name}}</span><span>{{n.address}}</span><span>{{n.state}}</span><span>{{n.agent_version||"—"}}</span></div></div></div></section>
<section v-else-if="section==='inbounds'"><div class="panel page"><div class="panel-head"><h2>این‌باندها</h2><button class="primary">+ Inbound جدید</button></div><div class="table"><div class="tr th"><span>نام</span><span>Protocol</span><span>Port</span><span>State</span></div><div class="tr" v-for="x in inboundRows" :key="x.id"><span>{{x.name}}</span><span>{{x.protocol}}</span><span>{{x.listen_port}}</span><span>{{x.desired_state}}</span></div></div></div></section>
<section v-else-if="section==='clients'"><div class="panel page"><div class="panel-head"><h2>کلاینت‌ها</h2><button class="primary">+ Client جدید</button></div><div class="table"><div class="tr th"><span>نام</span><span>Inbound</span><span>Address</span><span>Status</span></div><div class="tr" v-for="x in clientRows" :key="x.id"><span>{{x.name}}</span><span>{{x.inbound_id}}</span><span>{{x.assigned_address}}</span><span>{{x.status}}</span></div></div></div></section>
<section v-else-if="section==='traffic'"><div class="grid2"><div class="panel"><h2>Traffic</h2><strong>{{((trafficData.total_bytes||0)/1099511627776).toFixed(2)}} TB</strong><p>IN: {{((trafficData.bytes_in||0)/1073741824).toFixed(2)}} GB</p><p>OUT: {{((trafficData.bytes_out||0)/1073741824).toFixed(2)}} GB</p></div><div class="panel"><h2>Quota</h2><p>Enforcement توسط Worker انجام می‌شود.</p></div></div></section>
<section v-else-if="section==='audit'"><div class="panel page"><h2>Audit Logs</h2><div class="table"><div class="tr th"><span>Action</span><span>Resource</span><span>Result</span><span>Time</span></div><div class="tr" v-for="x in auditRows" :key="x.id"><span>{{x.action}}</span><span>{{x.resource}}</span><span>{{x.result}}</span><span>{{x.created_at}}</span></div></div></div></section>
<section v-else><div class="panel page"><h2>{{title}}</h2><div class="empty">این بخش به عنوان workspace مدیریت در نسخه 100 تعریف شده و APIهای مربوطه در Control Plane قرار دارند.</div></div></section>
</main></div>
</template>